   403	            CGEventSetLocation(tabletEvent, location);
   404	            CGEventSetIntegerValueField(tabletEvent, CGEventField.tabletEventPointButtons, semantics.TabletButtons);
   405	            CGEventSetIntegerValueField(tabletEvent, CGEventField.tabletEventDeviceID, DeviceId);
