   416	            ApplyEventFlags(tabletEvent);
   417	            CGEventPost(CGEventTapLocation.kCGHIDEventTap, tabletEvent);
   418	            CFRelease(tabletEvent);
   419	        }
   420	
   421	        private void ApplyEventFlags(IntPtr eventRef)
   422	        {
   423	            // This uses an undocumented flag that tells the system to automatically include the event flags in the event.
   424	            // It's a better approach than fetching the active event flags ourselves, as doing so can introduce a race condition
   425	            // (e.g., if a modifier key is released after we check its status but before the event is posted).
   426	            // However, this flag has not effects for synthetic keyboard events, so we manually set the flags if there are modifiers bindings.
   427	
   428	            if (_keyboard.getCurrentFlags() != 0)
   429	                CGEventSetFlags(eventRef, _keyboard.getCurrentFlags());
   430	            else
   431	                CGEventSetFlags(eventRef, ~0U);
   432	        }
