   463	            CGEventSetIntegerValueField(pressureEvent, CGEventField.mouseEventClickState, _clickState);
   464	            ApplyPressureMouseEventValues(pressureEvent);
   465	            LogTiming($"CGEventPost pressure-shadow type={_mouseEventType} subtype={CGMouseEventSubtype.TabletPoint} target={_mouseEventTargetKind} pressure={_pressure.GetValueOrDefault(0f):0.###} buttons=0x{_currButtonStates:X}");
