   467	            CFRelease(pressureEvent);
   468	        }
   469	
   470	        private MacOSPointerTargetKind ResolveTargetKind(CGPoint location) =>
   471	            _forcePlainMouseUntilRelease ? _forcedPlainMouseTargetKind : _windowActivator.GetCachedTargetKind(location);
