   476	        private static bool ShouldWarpCursor(CGEventType eventType)
   477	        {
   478	            return IsPointerMotionEvent(eventType);
   479	        }
   480	
   481	        private static bool IsPointerMotionEvent(CGEventType eventType)
   482	        {
   483	            return eventType is CGEventType.kCGEventMouseMoved or
   484	                                CGEventType.kCGEventLeftMouseDragged or
   485	                                CGEventType.kCGEventRightMouseDragged or
   486	                                CGEventType.kCGEventOtherMouseDragged;
   487	        }
   488	
   489	        private static void LogTiming(string message)
   490	        {
   491	            if (Interlocked.Increment(ref _timingLogs) <= 64)
   492	                Log.Debug("WH851 Timing", $"{Stopwatch.GetTimestamp()} {message}");
   493	        }
   494	
   495	        ~MacOSVirtualMouse()
   496	        {
