         private static bool DeviceMatchesAttribute(IDeviceEndpoint device, Dictionary<string, string>? identifier_attributes, Dictionary<string, string>? config_attributes)
         {
+            if (identifier_attributes != null)
+            {
+                foreach (var attribute in identifier_attributes)
+                {
+                    if (attribute.Key is "Interface" or "WinUsage")
+                        continue;
+
+                    if (!device.DeviceAttributes.TryGetValue(attribute.Key, out var value) || value != attribute.Value)
+                        return false;
+                }
