rows=[json.loads(l) for l in open(p) if l.strip()]
# Calculate min/max decoded x/y/pressure for pen reports
for phase,source in [('USB','usb.iohid'),('Bluetooth','bluetooth.corebluetooth')]:
  print('\n',phase)
  for step in ['pen button 1','pen button 2','pen tap']:
    vals=[]
    for r in rows:
      if r.get('kind')=='event' and r.get('phase')==phase and r.get('source')==source and r.get('step')==step and r.get('hex'):
        b=[int(x,16) for x in r['hex'].split('-')]
        if len(b)>=8:
          x=b[2] | (b[3]<<8); y=b[4] | (b[5]<<8); p=b[6] | (b[7]<<8)
          vals.append((b[1],x,y,p))
    if vals:
      print(step, 'status', sorted(set(v[0] for v in vals)), 'x',min(v[1] for v in vals),max(v[1] for v in vals),'y',min(v[2] for v in vals),max(v[2] for v in vals),'p',min(v[3] for v in vals),max(v[3] for v in vals))
